import os
import sqlite3
from contextlib import closing

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ.get("STRIPE_SECRET_KEY", "")
DB_PATH = os.environ.get("LMS_DB_PATH", "lms.db")
_VALID_REASONS = {"requested_by_customer", "duplicate", "fraudulent"}


def _refund_params(payment_intent_id, refund_amount_cents, reason):
    params = {"payment_intent": payment_intent_id}
    if refund_amount_cents is not None:
        if refund_amount_cents <= 0:
            raise ValueError("refund_amount_cents must be positive")
        params["amount"] = refund_amount_cents
    if reason:
        if reason not in _VALID_REASONS:
            raise ValueError(f"reason must be one of {sorted(_VALID_REASONS)}")
        params["reason"] = reason
    return params


@tool
def revoke_enrollment_and_refund(
    student_id: int,
    course_id: int,
    payment_intent_id: str,
    refund_amount_cents: int = None,
    reason: str = "requested_by_customer",
) -> dict:
    params = _refund_params(payment_intent_id, refund_amount_cents, reason)
    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        return {"ok": False, "error": f"Refund failed: {exc.user_message or str(exc)}"}

    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            progress = conn.execute(
                "DELETE FROM lesson_progress WHERE student_id = ? AND course_id = ?",
                (student_id, course_id),
            ).rowcount
            enrollments = conn.execute(
                "DELETE FROM enrollments WHERE student_id = ? AND course_id = ?",
                (student_id, course_id),
            ).rowcount

    return {
        "ok": True,
        "refund_id": refund.id,
        "refund_status": refund.status,
        "refunded_cents": refund.amount,
        "enrollments_deleted": enrollments,
        "progress_rows_deleted": progress,
    }

import os
import sqlite3
from datetime import datetime, timezone

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("lms-content")
DB = os.environ.get("LMS_DB_PATH", "lms.db")


def _cols(t, b, d, p):
    c = {}
    if t is not None:
        t = t.strip()
        if not t:
            raise ValueError("title cannot be empty")
        c["title"] = t
    if b is not None:
        c["body_markdown"] = b
    if d is not None:
        if d < 0:
            raise ValueError("duration_minutes must be non-negative")
        c["duration_minutes"] = d
    if p is not None:
        c["is_published"] = 1 if p else 0
    return c


@mcp.tool()
def update_lesson_details(
    lesson_id: int,
    title: str = None,
    body_markdown: str = None,
    duration_minutes: int = None,
    is_published: bool = None,
) -> dict:
    c = _cols(title, body_markdown, duration_minutes, is_published)
    if not c:
        return {"updated": False, "error": "No fields provided to update"}
    c["updated_at"] = datetime.now(timezone.utc).isoformat()
    s = ", ".join(f"{k} = ?" for k in c)
    v = list(c.values()) + [lesson_id]
    cn = sqlite3.connect(DB)
    try:
        cur = cn.execute(f"UPDATE lessons SET {s} WHERE id = ?", v)
        cn.commit()
        n = cur.rowcount
    finally:
        cn.close()
    if n == 0:
        return {"updated": False, "error": f"Lesson {lesson_id} not found"}
    return {"updated": True, "lesson_id": lesson_id, "fields": sorted(k for k in c if k != "updated_at")}
